      const roleLabel = state.role === 'display' ? '🖥 Anzeige (Laptop / Beamer)' : '🎹 Steuerung (iPad / Klavier)';
      const latencyTxt = state.latencyMs != null ? ` · ${state.latencyMs} ms` : '';
